import { MAP_DATA_BASE_URL } from "./map-data-url";
import en from "../../i18n/locales/en.json";
import type { MapRegion } from "./types";

/**
 * The maps this app ships. Each entry points at a directory holding
 * `metadata.json` and a `tiles/` pyramid (see scripts/build-map-from-tiles.mjs
 * for the expected layout). With more than one entry the map workspace shows
 * a map picker; with exactly one it stays hidden.
 *
 * `dataUrl` is usually `${MAP_DATA_BASE_URL}/<folder>` so the same registry
 * always loads map data from the release content CDN.
 */
export interface MapDefinition {
  id: string;
  /** Shown in the map picker until the map's own `displayName` has loaded. */
  name: string;
  dataUrl: string;
  /** Optional extra point layers bundled beside metadata.json. */
  locationFiles?: string[];
  /** Place this map in a dedicated shortcut beside the map picker. */
  quickJumpLabelKey?: string;
  /** Client subzones without world-map name actors need explicit label anchors. */
  regionLabels?: MapRegion[];
}

